// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 depositAmount, uint256 seed) public {
        depositAmount = bound(depositAmount, 1, type(uint128).max);

        address alice = address(uint160(uint256(keccak256(abi.encode("alice", seed)))));
        address bob = address(uint160(uint256(keccak256(abi.encode("bob", seed)))));
        vm.assume(alice != bob && alice != address(0) && bob != address(0));

        vm.deal(alice, depositAmount);
        vm.deal(bob, depositAmount);

        vm.prank(alice);
        c.addToBalance{value: depositAmount}();

        vm.prank(bob);
        c.addToBalance{value: depositAmount}();

        vm.prank(alice);
        c.withdrawBalance();

        uint256 bobBalance = c.getBalance(bob);
        uint256 aliceBalance = c.getBalance(alice);
        uint256 totalTracked = bobBalance + aliceBalance;

        assertTrue(totalTracked == address(c).balance);
    }
}
